#!/usr/bin/env python3
"""simcompare 단일 파일 실행기 (자동 생성: scripts/build_single_file.py). 소스 해시 6fec1f58878fcd0ebe6389f8ee75dbc915a216c71f492b6bb0bf129c92eca476.
서버 wrapper가 명령줄 인자를 넘기지 못할 때 쓴다. 아래 EDIT 블록만 고치고 이 파일을 그대로 실행한다."""
# 1회차: hotspot import. 끝나면 pairs.csv를 data/imported/reference/와 data/imported/target/ 안에 복사한다.
# 각 import는 --expected-cases-from-roots로 다른 모델의 root를 함께 주어, 기대 case 목록을 두 모델에서 발견된 case 이름의 합집합으로 만든다
# (한쪽에만 없는 case 폴더는 expected_case_folder_missing으로 보고된다. 두 모델 모두에 없는 case는 찾을 수 없다).
# 예전 실행기로 이미 import했다면(기대 목록 없음 → 4회차 ROI 전부 blocked) 1회차부터 다시 한다. 먼저 이전 출력 폴더를 옮기거나 이름을 바꾼다
# (--out은 없는 경로여야 한다): data/imported/reference·target, data/assets/reference·target, data/candidates_k3, data/confirmed.
# 회차 사이 수작업도 다시 한다: 1회차 뒤 pairs.csv 복사, 3회차 뒤 import 결과 배치와 real.yaml electrode_import_record.sha256 갱신.
# ============================== EDIT BELOW: 이 블록만 고치세요 ==============================
# 각 작업은 `python -m simcompare <명령> <인자...>`와 같다. 명령 이름은 import-hotspots, validate-data, compare,
# electrode-map, import-electrode-assets, export-review-rois, candidates, confirm-pairs, compare-windows, report 등이다.
# 인자는 명령줄에서 쓰던 그대로 문자열 리스트로 적는다. 상대 경로는 BASE_DIR 기준이다(아래). wrapper가 이 파일을 다른 곳에
# 복사해 실행하면 "이 .py가 있는 폴더"가 달라지므로, 상대 경로를 쓸 때는 BASE_DIR를 절대 경로로 적는 것이 안전하다.
# 작업은 위에서부터 차례로 실행된다. 종료 코드 0(완료)과 3(부분 결과)은 다음 작업으로 넘어가고, 그 밖의 코드는 멈춘다.
JOBS = [
    # reference (QA4_R00). --out은 아직 없는 새 경로
    ('import-hotspots', [
        '--root', 'data/input/hotspot/QA4_R00',
        '--expected-cases-from-roots', 'data/input/hotspot/QA4_T00',
        '--out', 'data/imported/reference',
    ]),
    # target (QA4_T00)
    ('import-hotspots', [
        '--root', 'data/input/hotspot/QA4_T00',
        '--expected-cases-from-roots', 'data/input/hotspot/QA4_R00',
        '--out', 'data/imported/target',
    ]),
]
LOG_FILE = 'runs/simcompare_1_import_hotspots.log'   # stdout/stderr를 이 파일에도 남긴다. 필요 없으면 None
WORK_DIR = None                               # 패키지를 풀 폴더. None이면 이 파일 옆, 쓸 수 없으면 임시 폴더
BASE_DIR = None                               # JOBS·LOG_FILE·WORK_DIR의 상대 경로 기준 폴더(절대 경로). None이면 이 .py가 있는 폴더
# ============================== EDIT ABOVE ==============================================

